head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.textbox1_onclick = function(e) {
    debugger;
    alert("isPopup() : " + $p.isPopup() + ", isWFramePopup() : " + $p.isWFramePopup());
};
scwin.textbox2_onclick = function(e) {
    debugger;
    localStorage.setItem("log", $p.isPopup(true));
    //alert("isPopup(true) : " + $p.isPopup(true) + ", isWFramePopup(true) : " +$p.isWFramePopup(true));
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
